import * as T from './vendor/three.module.min.js';
import {STAIRS,radialLimit,stairCenter,stairBoundary,treadHeight,treadRelief} from './level27-layout.js?v=64';
export function paintGeology(g){const p=g.attributes.position,c=[],wet=[];for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i),a=Math.atan2(z,x),waterline=1-T.MathUtils.smoothstep(y,.04,1.0),fall=Math.exp(-Math.pow((a+2.71)/.34,2))*(1-T.MathUtils.smoothstep(y,2.1,2.8)),shore=Math.max(0,Math.hypot(x,z)-radialLimit(x,z)),w=Math.max(waterline*(1-T.MathUtils.smoothstep(shore,.10,.85)),fall*.96);wet.push(w);c.push(1-.13*w,1-.08*w,1-.15*w);}g.setAttribute('color',new T.Float32BufferAttribute(c,3));g.setAttribute('caveWet',new T.Float32BufferAttribute(wet,1));if(g.attributes.uv&&!g.attributes.uv1)g.setAttribute('uv1',g.attributes.uv.clone());return g;}
export function configureGeology(mat,tex,clock,{bed=false,base=null}={}){mat.vertexColors=true;mat.onBeforeCompile=s=>{
 Object.assign(s.uniforms,{caveTime:clock,dryMap:{value:tex[base||(bed?'riverbed-pebbles':'limestone-dry')]},wetMap:{value:tex['limestone-wet']},dryNormal:{value:tex[(base||(bed?'riverbed-pebbles':'limestone-dry'))+'-normal']},wetNormal:{value:tex['limestone-wet-normal']},caveRough:{value:tex[(base||(bed?'riverbed-pebbles':'limestone-dry'))+'-roughness']},caveRipple:{value:tex['water-caustics']}});
 s.vertexShader='attribute float caveWet;varying float vWet;varying vec3 vRockP,vRockN;\n'+s.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvRockP=(modelMatrix*vec4(transformed,1.)).xyz;vRockN=normalize(mat3(modelMatrix)*normal);vWet=caveWet;');
 s.fragmentShader=`varying float vWet;varying vec3 vRockP,vRockN;uniform sampler2D dryMap,wetMap,dryNormal,wetNormal,caveRough,caveRipple;uniform float caveTime;
 vec3 tri(sampler2D tex,vec3 p,vec3 n){vec3 w=pow(abs(n),vec3(5.));w/=max(dot(w,vec3(1.)),.001);return texture2D(tex,p.zy).rgb*w.x+texture2D(tex,p.xz).rgb*w.y+texture2D(tex,p.xy).rgb*w.z;}
 vec3 triNormal(sampler2D tex,vec3 p,vec3 n){vec3 w=pow(abs(n),vec3(5.));w/=max(dot(w,vec3(1.)),.001);vec3 a=texture2D(tex,p.zy).xyz*2.-1.,b=texture2D(tex,p.xz).xyz*2.-1.,c=texture2D(tex,p.xy).xyz*2.-1.;return normalize(vec3(a.z*sign(n.x),a.y,a.x)*w.x+vec3(b.x,b.z*sign(n.y),b.y)*w.y+vec3(c.x,c.y,c.z*sign(n.z))*w.z);}
 `+s.fragmentShader;
 s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>',`vec3 albedo=mix(tri(dryMap,vRockP*.79,vRockN),tri(wetMap,vRockP*.87,vRockN),vWet*.84);diffuseColor.rgb*=albedo;`);
 s.fragmentShader=s.fragmentShader.replace('#include <normal_fragment_maps>',`vec3 trN=normalize(mix(triNormal(dryNormal,vRockP*.79,vRockN),triNormal(wetNormal,vRockP*.87,vRockN),vWet));normal=normalize(mix(normal,mat3(viewMatrix)*trN*faceDirection,.57));`);
 s.fragmentShader=s.fragmentShader.replace('#include <roughnessmap_fragment>',`float roughnessFactor=mix(.76*tri(caveRough,vRockP*.79,vRockN).g,.09,vWet);`);
 s.fragmentShader=s.fragmentShader.replace('#include <opaque_fragment>',`float ca=texture2D(caveRipple,vRockP.xz*.87+vec2(caveTime*.017,-caveTime*.011)).r;float cb=texture2D(caveRipple,vRockP.xz*.91+vec2(-caveTime*.014,caveTime*.018)).r;outgoingLight+=vec3(.065,.13,.095)*pow(min(ca,cb),1.6)*(1.-smoothstep(-.3,.65,vRockP.y));\n#include <opaque_fragment>`);
 };mat.customProgramCacheKey=()=>base|| (bed?'spring-bed-v63':'spring-triplanar-normal-wet-v63');}
export function naturalTreads(mat){const root=new T.Group();root.name='Ten contiguous weathered natural rock treads';for(let k=0;k<STAIRS.count;k++){const start=STAIRS.start+k*STAIRS.tread,p=[],uv=[],ix=[],nx=40,nz=24;
 for(let j=0;j<=nz;j++)for(let i=0;i<=nx;i++){const v=j/nz,u=i/nx-.5;let z=start+v*STAIRS.tread,x;for(let n=0;n<4;n++){x=stairCenter(z)+u*STAIRS.width+.067*Math.sin(v*5.3+k*1.8)*Math.pow(Math.abs(u)*2,6);z=stairBoundary(k,x)*(1-v)+stairBoundary(k+1,x)*v;}const y=treadHeight(k)+treadRelief(x,z,{i:k,v});p.push(x,y,z);uv.push(x*.8,z*.8);}
 for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){let a=j*(nx+1)+i,b=a+nx+1;ix.push(a,b,a+1,a+1,b,b+1);}
 // Connect tread fronts and flanks down into bedrock; chipped boundaries stay outside walking core.
 const borders=[Array.from({length:nx+1},(_,i)=>i),Array.from({length:nx+1},(_,i)=>nz*(nx+1)+i),Array.from({length:nz+1},(_,j)=>j*(nx+1)),Array.from({length:nz+1},(_,j)=>j*(nx+1)+nx)];
 for(const edge of borders)for(let j=0;j<edge.length-1;j++){let a=edge[j],b=edge[j+1];const aa=a,bb=b;for(let layer=1;layer<=7;layer++){const f=layer/7,base=p.length/3;for(const id of[aa,bb]){const ox=p[id*3],oz=p[id*3+2],shrink=Math.sin(f*Math.PI)*(.14+.045*Math.sin(ox*12+oz*13+k)),cx=stairCenter(oz),cz=(stairBoundary(k,ox)+stairBoundary(k+1,ox))*.5;p.push(ox+(cx-ox)*shrink,p[id*3+1]*(1-f)+.19*f,oz+(cz-oz)*shrink);uv.push(ox,oz);}ix.push(a,base,b,b,base,base+1);a=base;b=base+1;}}
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();paintGeology(g);const mesh=new T.Mesh(g,mat);mesh.name='Weathered tread '+(k+1);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);}return root;}
export function organicStone(mat,position,scale,seed=0){const g=new T.SphereGeometry(1,18,12),p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i),r=1+.08*Math.sin(x*7+y*4+seed)*Math.cos(z*8-y*3)+.035*Math.sin(z*19+x*13);p.setXYZ(i,x*r,y*r,z*r);}g.computeVertexNormals();const o=new T.Mesh(g,mat);o.position.fromArray(position);o.scale.fromArray(scale);o.castShadow=o.receiveShadow=true;return o;}
